//! Cargo-driven `wow64.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is wow64-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", None),
        o => panic!("wow64-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86_64" => &["body", "import:win32u", "import:ntdll"],
        "aarch64" => &["body", "import:win32u", "import:ntdll"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/wow64",
        "dll/win32/wow64",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("wow64-rust")
        .c_from_compile_db("wow64_shims", &["dll/win32/wow64/rust_cohab_stub.c"])
        .rc("dll/win32/wow64/wow64.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/wow64/wow64.spec", "wow64.dll")
        .import_lib("win32ss/win32u/win32u.spec", "win32u.dll", "win32u")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
